#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-component-spec.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-component-spec.mjs
 *
 * @version 3
 * @updated 2026-06-05
 *
 * Enforces the component spec.yaml schema for design-system primitives. Components
 * are discovered via the shared `_discover-components.mjs` helper (path-agnostic:
 * components/ui/<Name>/, generic components/<Name>/, and feature-located
 * <feature>/components/<name>/), NOT only src/components/ui/.
 *
 * Required top-level fields:
 *   spec_version (int), component (string), package (string), folder (path),
 *   status (enum: draft|locked), api_shape (enum: MUI|DaisyUI|shadcn|custom-justified)
 *
 * spec.yaml is IMPLEMENTATION-ONLY. Required blocks (each must exist and be non-empty):
 *   public_api, tokens_consumed, state_classes_consumed, test_coverage
 * The narrative (anatomy, ARIA/keyboard, WCAG contrast, responsive/forced-colors/
 * reduced-motion/rtl/print strategies, edge cases, exploration, decisions) lives in
 * spec.md — see SPEC_CONTRACT.spec_yaml_vs_spec_md.
 *
 * "n/a — <reason>" is acceptable for any optional row inside a block.
 *
 * Usage:
 *   node verify-component-spec.mjs [src-root]
 *   default src-root: "src"
 *
 * Dep: requires `yaml` (the `yaml` npm package) as a project devDep, OR
 *      a Node-resolvable copy in any walked ancestor's node_modules.
 *
 * Exit: 0 on green, 1 on any spec violation.
 *
 * Per COMPONENT_CREATION.yaml.verifiers.verify-component-spec.
 */

import { readFileSync, existsSync } from "node:fs";
import { join, relative, basename, dirname } from "node:path";
import { createRequire } from "node:module";
import { discoverSpeccedComponents } from "./_discover-components.mjs";
import { applyExceptions } from "./_load-exceptions.mjs";

const RULE_ID = "verify-component-spec";

const SRC_ROOT = process.argv[2] || "src";
const REPO_ROOT = process.cwd();
const absRoot = join(REPO_ROOT, SRC_ROOT);



const REQUIRED_TOP_LEVEL = [
  "spec_version", "component", "package", "folder", "status", "api_shape",
];

const VALID_API_SHAPES = new Set(["MUI", "DaisyUI", "shadcn", "custom-justified"]);
const VALID_STATUS = new Set(["draft", "locked"]);

// spec.yaml is IMPLEMENTATION-ONLY: the contract a coder builds against. The
// narrative — anatomy, ARIA/keyboard, WCAG contrast, responsive/forced-colors/
// reduced-motion/rtl/print strategies, edge cases, exploration, decisions — lives
// in spec.md (prose), not here. (Verifier slimmed 2026-06-13 per the spec.yaml/
// spec.md split.) Optional impl blocks (interaction_states, a11y) may still appear
// in spec.yaml and are validated when present, but are not required.
const REQUIRED_BLOCKS = [
  "public_api",
  "tokens_consumed",
  "state_classes_consumed",
  "test_coverage",
];
const REQUIRED_BLOCKS_WITH_VARIANTS = REQUIRED_BLOCKS;
const REQUIRED_BLOCKS_WITHOUT_VARIANTS = REQUIRED_BLOCKS;

const require = createRequire(import.meta.url);

function resolveYaml(specPath) {
  // Try local require first (the spec's own project).
  try {
    return require("yaml");
  } catch {}
  // Walk up from spec dir to find any node_modules/yaml.
  let dir = dirname(specPath);
  while (dir !== "/") {
    const candidate = join(dir, "node_modules", "yaml");
    if (existsSync(candidate)) {
      try {
        return createRequire(join(candidate, "package.json"))("yaml");
      } catch {}
    }
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

if (!existsSync(absRoot)) {
  process.stdout.write(
    `✅ verify-component-spec — no ${SRC_ROOT}/ in this repo; nothing to check.\n`,
  );
  process.exit(0);
}

const specPaths = discoverSpeccedComponents(absRoot).map((c) => c.specPath);

if (specPaths.length === 0) {
  process.stdout.write(
    `✅ verify-component-spec — no component spec.yaml found under ${SRC_ROOT}/ (components/ui, components/, or feature-located components/).\n`,
  );
  process.exit(0);
}

const violations = [];

function isMissingOrEmpty(value) {
  if (value === undefined || value === null) return true;
  if (typeof value === "string" && value.trim().length === 0) return true;
  if (Array.isArray(value) && value.length === 0) return true;
  if (typeof value === "object" && Object.keys(value).length === 0) return true;
  return false;
}

// Collect every spec violation for ONE component into a local array, so a
// per-feature exception.yaml can waive the whole set (and log the reason) before
// it reaches the global tally. Returns [] when the spec is a composite/page tier
// (handled by the composite/page verifiers).
function collectSpecViolations(specPath, rel) {
  const local = [];
  const YAML = resolveYaml(specPath);
  if (!YAML) {
    local.push(`${rel}: cannot resolve \`yaml\` package. Install it: pnpm add -D yaml`);
    return local;
  }

  let doc;
  try {
    doc = YAML.parse(readFileSync(specPath, "utf8"));
  } catch (e) {
    local.push(`${rel}: YAML parse error — ${e.message}`);
    return local;
  }
  if (!doc || typeof doc !== "object") {
    local.push(`${rel}: spec is empty or not a YAML object`);
    return local;
  }

  // Tier separation: this verifier enforces the ATOMIC (tier-1) spec schema only.
  // Composites (tier: composite) and pages (tier: page) carry their own schema
  // (consumed_atomics / composition_anatomy / …) and are verified by
  // verify-composite-* / verify-page-*; they do NOT carry the atomic's anatomy /
  // interaction_states / variant matrix (per COMPOSITE_CREATION/PAGE_CREATION).
  if (doc.tier === "composite" || doc.tier === "page") return local;

  // Top-level fields.
  for (const field of REQUIRED_TOP_LEVEL) {
    if (isMissingOrEmpty(doc[field])) {
      local.push(`${rel}: missing required top-level field \`${field}\``);
    }
  }

  if (doc.api_shape && !VALID_API_SHAPES.has(doc.api_shape)) {
    local.push(
      `${rel}: api_shape="${doc.api_shape}" is not one of [${[...VALID_API_SHAPES].join(", ")}]`,
    );
  }
  if (doc.status && !VALID_STATUS.has(doc.status)) {
    local.push(
      `${rel}: status="${doc.status}" is not one of [${[...VALID_STATUS].join(", ")}]`,
    );
  }

  // Required blocks (variant-aware).
  const hasVariants = doc.has_variants !== false; // default true
  const required = hasVariants
    ? REQUIRED_BLOCKS_WITH_VARIANTS
    : REQUIRED_BLOCKS_WITHOUT_VARIANTS;

  for (const block of required) {
    if (isMissingOrEmpty(doc[block])) {
      local.push(
        `${rel}: missing required block \`${block}\` (or it is empty)` +
          (!hasVariants ? "" : " — set top-level has_variants:false if this component genuinely has no variants"),
      );
    }
  }

  // Touch target sanity check.
  if (doc.touch_target_minima && !isMissingOrEmpty(doc.touch_target_minima)) {
    if (!doc.touch_target_minima.wcag_sc || !doc.touch_target_minima.min_px) {
      local.push(`${rel}: touch_target_minima must declare \`wcag_sc\` and \`min_px\``);
    }
  }

  // Contrast pairs: every passes:false row must carry a deviation explanation.
  if (Array.isArray(doc.wcag_aa_contrast_pairs)) {
    for (const pair of doc.wcag_aa_contrast_pairs) {
      if (pair && pair.passes === false && isMissingOrEmpty(pair.deviation)) {
        const combo = pair.combo || "<unknown>";
        local.push(
          `${rel}: contrast pair \`${combo}\` fails AA but lacks \`deviation:\` justification`,
        );
      }
    }
  }
  return local;
}

for (const specPath of specPaths) {
  const rel = relative(REPO_ROOT, specPath);
  const compDir = dirname(dirname(specPath)); // specPath = <dir>/__specs__/spec.yaml
  const local = collectSpecViolations(specPath, rel);
  violations.push(
    ...applyExceptions({ dir: compDir, ruleId: RULE_ID, violations: local, rel }),
  );
}

if (violations.length === 0) {
  process.stdout.write(
    `✅ verify-component-spec — ${specPaths.length} spec(s) checked; all required blocks present.\n`,
  );
  process.exit(0);
}

process.stderr.write(
  `❌ verify-component-spec: ${violations.length} violation(s)\n\n`,
);
for (const v of violations) process.stderr.write(`  ${v}\n`);
process.stderr.write(
  `\nPer COMPONENT_CREATION.yaml.component_spec_schema, every required block must be present.\n` +
    `Template: ~/.claude/standards/templates/component-spec.yaml.template\n`,
);
process.exit(1);
